package mrpapermoon.whisper.screenimport androidx.compose.foundation.layout.paddingimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.layout.layoutimport androidx.compose.ui.tooling.preview.Previewimport androidx.compose.ui.unit.dpimport mrpapermoon.whisper.ui.theme.WhisperColorsimport mrpapermoon.whisper.ui.theme.WhisperThemeimport mrpapermoon.whisper.ui.widget.BrandBackgroundimport mrpapermoon.whisper.ui.widget.WhisperWaveBar// TODO: hilt https://www.google.com/search?q=architecture&sourceid=chrome&ie=UTF-8&amc=1&udm=50&aep=48&cud=0&source=chrome.crn.obic&mstk=AUtExfC2u76EWCeIL8K4TXFuZD5-ZCkbBXdUz4KqTjrPJ6Dg7PDqAEOQf4E9RXDEvpE11C4vUGjopq83TpP3F4TIbjewWxI3x3JBoCvd0aEo-_54VBxaOvVYx5LASNf2i215QPx9MVKyDmKsKa-AGPkNtzbb9s2SJZlRNAipM1jXFRgptxiBVGJ7tSowMJMle0P_YkA7buQ68yep0mJkq4ie4Ko4hBVoAVOJ22KwThjHwqfVujlrLEJjinK4joqxff7vKBchekros9x-Mw&csuir=1&mtid=b0TRavrYE7HUwPAP5_K7gQQ@Composablefun SplashScreen(modifier: Modifier = Modifier) {	BrandBackground(modifier = modifier, padding = 16.dp) {		WhisperWaveBar(			modifier = Modifier				.padding(horizontal = 4.dp)				.layout { measurable, constraints ->					val placeable = measurable.measure(constraints)					val baselineY = (constraints.maxHeight * 3) / 4					val x = (constraints.maxWidth - placeable.width) / 2					val y = (baselineY - placeable.height).coerceAtLeast(0)					layout(constraints.maxWidth, constraints.maxHeight) {						placeable.placeRelative(x, y)					}				},			waveColor = WhisperColors.primary_200,			strokeWidth = 2.dp,		)	}}@Preview@Composablefun SplashScreenPreview() {	WhisperTheme {		SplashScreen()	}}